const mqtt = require("mqtt");

module.exports = function (RED) {
  const url = process.env.TRACE_BROKER || "mqtt://mqtt:1883";
  const topic = process.env.TRACE_TOPIC || "nodered/trace";
  const client = mqtt.connect(url, { clientId: "flow-trace-" + process.pid });

  const pub = (ev) => client.connected && client.publish(topic, JSON.stringify(ev));

  RED.plugins.registerPlugin("flow-trace", {
    onadd: () => {
      RED.hooks.add("onReceive.flow-trace", (ev) => {
        const n = ev.destination.node;
        pub({ phase: "enter", nodeId: n.id, type: n.type, name: n.name,
              z: n.z, msgid: ev.msg._msgid, t: Date.now() });
      });

      RED.hooks.add("postReceive.flow-trace", (ev) => {
        const n = ev.destination.node;
        pub({ phase: "exit", nodeId: n.id, msgid: ev.msg._msgid, t: Date.now() });
      });

      RED.log.info("flow-trace: publishing to " + url + " " + topic);
    },
    onremove: () => RED.hooks.remove("*.flow-trace")
  });
};